    "original": "# Usage: copy_or_skip REV TREE NEWPARENTS\ncopy_or_skip () {\n\tassert test $# = 3\n\trev=\"$1\"\n\ttree=\"$2\"\n\tnewparents=\"$3\"\n\tassert test -n \"$tree\"\n\n\tidentical=\n\tnonidentical=\n\tp=\n\tgotparents=\n\tcopycommit=\n\tfor parent in $newparents\n\tdo\n\t\tptree=$(toptree_for_commit $parent) || exit $?\n\t\ttest -z \"$ptree\" && continue\n\t\tif test \"$ptree\" = \"$tree\"\n\t\tthen\n\t\t\t# an identical parent could be used in place of this rev.\n\t\t\tif test -n \"$identical\"\n\t\t\tthen\n\t\t\t\t# if a previous identical parent was found, check whether\n\t\t\t\t# one is already an ancestor of the other\n\t\t\t\tmergebase=$(git merge-base $identical $parent)\n\t\t\t\tif test \"$identical\" = \"$mergebase\"\n\t\t\t\tthen\n\t\t\t\t\t# current identical commit is an ancestor of parent\n\t\t\t\t\tidentical=\"$parent\"\n\t\t\t\telif test \"$parent\" != \"$mergebase\"\n\t\t\t\tthen\n\t\t\t\t\t# no common history; commit must be copied\n\t\t\t\t\tcopycommit=1\n\t\t\t\tfi\n\t\t\telse\n\t\t\t\t# first identical parent detected\n\t\t\t\tidentical=\"$parent\"\n\t\t\tfi\n\t\telse\n\t\t\tnonidentical=\"$parent\"\n\t\tfi\n\n\t\t# sometimes both old parents map to the same newparent;\n\t\t# eliminate duplicates\n\t\tis_new=1\n\t\tfor gp in $gotparents\n\t\tdo\n\t\t\tif test \"$gp\" = \"$parent\"\n\t\t\tthen\n\t\t\t\tis_new=\n\t\t\t\tbreak\n\t\t\tfi\n\t\tdone\n\t\tif test -n \"$is_new\"\n\t\tthen\n\t\t\tgotparents=\"$gotparents $parent\"\n\t\t\tp=\"$p -p $parent\"\n\t\tfi\n\tdone\n\n\tif test -n \"$identical\" && test -n \"$nonidentical\"\n\tthen\n\t\textras=$(git rev-list --count $identical..$nonidentical)\n\t\tif test \"$extras\" -ne 0\n\t\tthen\n\t\t\t# we need to preserve history along the other branch\n\t\t\tcopycommit=1\n\t\tfi\n\tfi\n\tif test -n \"$identical\" && test -z \"$copycommit\"\n\tthen\n\t\techo $identical\n\telse\n\t\tcopy_commit \"$rev\" \"$tree\" \"$p\" || exit $?\n\tfi\n}\n\n# Usage: ensure_clean\nensure_clean () {\n\tassert test $# = 0\n\tif ! git diff-index HEAD --exit-code --quiet 2>&1\n\tthen\n\t\tdie \"fatal: working tree has modifications.  Cannot add.\"\n\tfi\n\tif ! git diff-index --cached HEAD --exit-code --quiet 2>&1\n\tthen\n\t\tdie \"fatal: index has modifications.  Cannot add.\"\n\tfi\n}\n\n# Usage: ensure_valid_ref_format REF\nensure_valid_ref_format () {\n\tassert test $# = 1\n\tgit check-ref-format \"refs/heads/$1\" ||\n\t\tdie \"fatal: '$1' does not look like a ref\"\n}\n\n# Usage: process_split_commit REV PARENTS\nprocess_split_commit () {\n\tassert test $# = 2\n\tlocal rev=\"$1\"\n\tlocal parents=\"$2\"\n\n\tif test $indent -eq 0\n\tthen\n\t\trevcount=$(($revcount + 1))\n\telse\n\t\t# processing commit without normal parent information;\n\t\t# fetch from repo\n\t\tparents=$(git rev-parse \"$rev^@\")\n\t\textracount=$(($extracount + 1))\n\tfi\n\n\tprogress \"$revcount/$revmax ($createcount) [$extracount]\"\n\n\tdebug \"Processing commit: $rev\"\n\tlocal indent=$(($indent + 1))\n\texists=$(cache_get \"$rev\") || exit $?\n\tif test -n \"$exists\"\n\tthen\n\t\tdebug \"prior: $exists\"\n\t\treturn\n\tfi\n\tcreatecount=$(($createcount + 1))\n\tdebug \"parents: $parents\"\n\tcheck_parents $parents\n\tnewparents=$(cache_get $parents) || exit $?\n\tdebug \"newparents: $newparents\"\n\n\ttree=$(subtree_for_commit \"$rev\" \"$dir\") || exit $?\n\tdebug \"tree is: $tree\"\n\n\t# ugly.  is there no better way to tell if this is a subtree\n\t# vs. a mainline commit?  Does it matter?\n\tif test -z \"$tree\"\n\tthen\n\t\tset_notree \"$rev\"\n\t\tif test -n \"$newparents\"\n\t\tthen\n\t\t\tcache_set \"$rev\" \"$rev\"\n\t\tfi\n\t\treturn\n\tfi\n\n\tnewrev=$(copy_or_skip \"$rev\" \"$tree\" \"$newparents\") || exit $?\n\tdebug \"newrev is: $newrev\"\n\tcache_set \"$rev\" \"$newrev\"\n\tcache_set latest_new \"$newrev\"\n\tcache_set latest_old \"$rev\"\n}\n\n# Usage: cmd_add REV\n#    Or: cmd_add REPOSITORY REF\ncmd_add () {\n\n\tensure_clean\n\n\tif test $# -eq 1\n\tthen\n\t\tgit rev-parse -q --verify \"$1^{commit}\" >/dev/null ||\n\t\t\tdie \"fatal: '$1' does not refer to a commit\"\n\n\t\tcmd_add_commit \"$@\"\n\n\telif test $# -eq 2\n\tthen\n\t\t# Technically we could accept a refspec here but we're\n\t\t# just going to turn around and add FETCH_HEAD under the\n\t\t# specified directory.  Allowing a refspec might be\n\t\t# misleading because we won't do anything with any other\n\t\t# branches fetched via the refspec.\n\t\tensure_valid_ref_format \"$2\"\n\n\t\tcmd_add_repository \"$@\"\n\telse\n\t\tsay >&2 \"fatal: parameters were '$*'\"\n\t\tdie \"Provide either a commit or a repository and commit.\"\n\tfi\n}\n\n# Usage: cmd_add_repository REPOSITORY REFSPEC\ncmd_add_repository () {\n\tassert test $# = 2\n\techo \"git fetch\" \"$@\"\n\trepository=$1\n\trefspec=$2\n\tgit fetch \"$@\" || exit $?\n\tcmd_add_commit FETCH_HEAD\n}\n\n# Usage: cmd_add_commit REV\ncmd_add_commit () {\n\t# The rev has already been validated by cmd_add(), we just\n\t# need to normalize it.\n\tassert test $# = 1\n\trev=$(git rev-parse --verify \"$1^{commit}\") || exit $?\n\n\tdebug \"Adding $dir as '$rev'...\"\n\tif test -z \"$arg_split_rejoin\"\n\tthen\n\t\t# Only bother doing this if this is a genuine 'add',\n\t\t# not a synthetic 'add' from '--rejoin'.\n\t\tgit read-tree --prefix=\"$dir\" $rev || exit $?\n\tfi\n\tgit checkout -- \"$dir\" || exit $?\n\ttree=$(git write-tree) || exit $?\n\n\theadrev=$(git rev-parse --verify HEAD) || exit $?\n\tif test -n \"$headrev\" && test \"$headrev\" != \"$rev\"\n\tthen\n\t\theadp=\"-p $headrev\"\n\telse\n\t\theadp=\n\tfi\n\n\tif test -n \"$arg_addmerge_squash\"\n\tthen\n\t\trev=$(new_squash_commit \"\" \"\" \"$rev\") || exit $?\n\t\tcommit=$(add_squashed_msg \"$rev\" \"$dir\" |\n\t\t\tgit commit-tree $arg_gpg_sign \"$tree\" $headp -p \"$rev\") || exit $?\n\telse\n\t\trevp=$(peel_committish \"$rev\") || exit $?\n\t\tcommit=$(add_msg \"$dir\" $headrev \"$rev\" |\n\t\t\tgit commit-tree $arg_gpg_sign \"$tree\" $headp -p \"$revp\") || exit $?\n\tfi\n\tgit reset \"$commit\" || exit $?\n\n\tsay >&2 \"Added dir '$dir'\"\n}\n",
